<template>
  <div id="home-container">
    <!-- 头部区域 -->
    <van-nav-bar title="小程序" fixed="true" placeholder="true" />
    <!--导入  注册 并使用 Article 组件  -->
    <van-pull-refresh
      v-model="isLoading"
      @refresh="onRefresh"
      :disabled="finished"
    >
      <van-list
        v-model="loading"
        :loading-text="加载中"
        :finished="finished"
        :finished-text="没有更多了"
        @load="onLoad"
      >
        <Articleinfo
          v-for="item in artList"
          :key="item.id"
          :title="item.title"
          :author="item.aut_name"
          :cmtCount="item.comm_count"
          :pubdate="item.pubdate"
          :cover="item.cover"
        ></Articleinfo>
      </van-list>
    </van-pull-refresh>
  </div>
</template>

<script>
//导入 request.js
import request from "@/utils/request";
import { getArticleListAPI } from "@/api/articleAPI.js";

import Articleinfo from "@/components/Article/Articleinfo";
//鲁大师  提供了许多牛逼的函数  节流的函数，防抖的函数，操作数组的一系列函数，操作对象的一系列函数
import _ from "lodash";
let fn = null;
export default {
  name: "Home",
  data() {
    return {
      //页码值
      page: 1,
      //每页显示多少数据
      limit: 10,
      //文章数组
      artList: [],
      //是否正在加载下一页数据    loading为true则不会反复触发load事件
      // 每当下一页数据请求回来之后，把loading从true改为false
      loading: true,
      //所有数据是否加载完毕了，如果没有更多数据了，把finished改成true
      finished: false,
      //是否正在下拉刷新
      isLoading: false,
    };
  },
  methods: {
    //封装获取文章列表数据的方法
    async initArticalList(isRefresh) {
      //发起 GET 请求，获取文章的列表数据
      const { data: res } = await getArticleListAPI(this.page, this.limit);
      //如果是上拉加载更多，那么应该是：
      //this.artist =[旧数据在前，新数据在后]
      if (isRefresh) {
        //下拉刷新   新数据在前，旧数据在后
        this.artList = [...res, ...this.artList];
        this.isLoading = false;
      } else {
        //上拉刷新  新数据在后，旧数据在前
        this.artList = [...this.artList, ...res];
        this.loading = false;
      }

      // console.log(res);
      if (res.length == 0) {
        //证明没有下一页了，把finish改为true 表示数据加载完了
        this.finished = true;
      }
    },
    //只要onLoad被调用，就请求下一页数据
    onLoad() {
      // console.log("触发了");
      //1.让页码值加1
      this.page++;
      //2.重新请求接口获取数据
      this.initArticalList();
    },
    //下拉刷新的处理函数
    onRefresh() {
      //1.让页码值+1
      this.page++;
      //2.重新请求接口获取数据
      this.initArticalList(true);
      console.log("刷新了");
    },
    //
    recordTopHander() {
      return _.debounce(
        () => {
          this.$route.meta.top = window.scrollY;
        },
        50,
        {
          trailing: true,
        }
      );
    },
  },
  created() {
    this.initArticalList();
  },
  activated() {
    fn = this.recordTopHander();
    window.addEventListener("scroll", fn);
  },
  deactivated() {
    window.removeEventListener("scroll", fn);
  },
  //注册组件
  components: {
    Articleinfo,
  },
};
</script>

