<template>
  <div>
    <van-cell>
      <!-- 标题区域的插槽 -->
      <template #title>
        <div class="title-box">
          <!-- 标题 -->
          <span>{{ title }}</span>
          <!-- 单张照片 -->
          <img
            :src="cover.images[0]"
            alt=""
            class="thumb"
            v-if="cover.type === 1"
          />
        </div>
        <!-- 三张图片 -->
        <div class="thumb-box" v-if="cover.type === 3">
          <img
            :src="item"
            alt=""
            class="thumb"
            v-for="(item, i) in cover.images"
            :key="i"
          />
        </div>
      </template>
      <!-- label 区域的插槽 -->
      <template #label>
        <div class="label-box">
          <span
            >作者 {{ author }} &nbsp;&nbsp; {{ cmtCount }} 评论 &nbsp;&nbsp;
            发布日期 {{ pubdate }}</span
          >
          <!-- 关闭按钮 -->
          <van-icon name="cross"></van-icon></div
      ></template>
    </van-cell>
  </div>
</template>

<script>
export default {
  props: {
    //文章标题
    title: {
      type: String,
      default: "",
    },
    //作者名字
    author: {
      type: String,
      default: "",
    },
    //评论数
    cmtCount: {
      //通过数组形式  为当前属性定义多个可能的类型
      type: [Number, String], //这里面包含了可能的类型
      default: 0,
    },
    //发布日期
    pubdate: {
      type: String,
      default: "",
    },
    //封面的信息对象
    cover: {
      type: Object,
      default: {},
    },
  },
};
</script>

<style lang='less' scoped>
.label-box {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.thumb {
  //矩形黄金比例  0.618
  width: 113px;
  height: 70px;
  background-color: #f8f8f8;
  //cover 	保持原有尺寸比例。但部分内容可能被剪切。
  object-fit: cover; //object-fit 属性指定元素的内容应该如何去适应指定容器的高度与宽度。
}
.title-box {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.thumb-box {
  display: flex;
  justify-content: space-between;
}
</style>