import Vue from 'vue'
import VueRouter from 'vue-router'
//导入需要的组件
import User from '@/views/User/User'
import Home from '@/views/Home/Home'
import Add from '@/views/Add/Add'
import Select from '@/views/Select/Select'
import Knowledge from '@/views/Knowledge/Knowledge'
//把 vueRouter 安装为 Vue 的插件
Vue.use(VueRouter)
    //路由规则的数组
const routes = [{
            path: '/',
            component: Home,
            //路由原信息，用来记录top值
            meta: {
                isRecord: true,
                top: 0
            }
        },
        {
            path: '/user',
            component: User
        },
        {
            path: '/knowledge',
            component: Knowledge
        },
        {
            path: '/add',
            component: Add
        },
        {
            path: '/select',
            component: Select
        }
    ]
    //创建路由实例对象
const router = new VueRouter({
    routes,
    //页面滚动时候的一个行为
    scrollBehavior(to, from, savedPosition) {
        //return 期望滚动到那个的位置
        if (savedPosition) {
            return savedPosition
        } else {
            return {
                x: 0,
                y: to.meta.top || 0
            }
        }
    }
})

export default router